def find_matching_combinations(customers, orders, items):
    """
    Find every (customer, order, item) combination where IDs match.

    Args:
        customers: List of customer dictionaries with 'id' key
        orders: List of order dictionaries with 'id' and 'customer_id' keys
        items: List of item dictionaries with 'order_id' key

    Returns:
        List of tuples (customer, order, item) where IDs match
    """
    combinations = []

    for customer in customers:
        for order in orders:
            if customer['id'] == order['customer_id']:
                for item in items:
                    if order['id'] == item['order_id']:
                        combinations.append((customer, order, item))

    return combinations


def find_matching_combinations_optimized(customers, orders, items):
    """
    Optimized version using dictionaries for O(n) lookups instead of O(n^3).

    Args:
        customers: List of customer dictionaries with 'id' key
        orders: List of order dictionaries with 'id' and 'customer_id' keys
        items: List of item dictionaries with 'order_id' key

    Returns:
        List of tuples (customer, order, item) where IDs match
    """
    # Build lookup dictionaries
    customer_dict = {customer['id']: customer for customer in customers}

    # Group orders by customer_id
    orders_by_customer = {}
    for order in orders:
        customer_id = order['customer_id']
        if customer_id not in orders_by_customer:
            orders_by_customer[customer_id] = []
        orders_by_customer[customer_id].append(order)

    # Group items by order_id
    items_by_order = {}
    for item in items:
        order_id = item['order_id']
        if order_id not in items_by_order:
            items_by_order[order_id] = []
        items_by_order[order_id].append(item)

    combinations = []

    for customer_id, customer in customer_dict.items():
        customer_orders = orders_by_customer.get(customer_id, [])
        for order in customer_orders:
            order_items = items_by_order.get(order['id'], [])
            for item in order_items:
                combinations.append((customer, order, item))

    return combinations


